using System.Diagnostics;
namespace ImageGuide;
public static class CoreControlSelfTests
{
    sealed class InlineProgress(Action<JobProgress> action):IProgress<JobProgress>{public void Report(JobProgress value)=>action(value);}
    static void Check(bool condition,string message){if(!condition)throw new Exception(message);}
    static void Canceled(Action action){try{action();}catch(OperationCanceledException){return;}throw new Exception("Expected cancellation acknowledgement");}
    public static int Run()
    {
        int passed=0;void Test(string name,Action action){action();Console.WriteLine("PASS "+name);passed++;}
        Test("pause waits then resume continues",()=>{using var c=new JobControl();c.RequestPause();var task=Task.Run(()=>c.Checkpoint("fixture"));Check(SpinWait.SpinUntil(()=>c.IsPaused,5000),"Did not pause");Check(!task.IsCompleted,"Paused task advanced");c.Resume();Check(task.Wait(5000),"Resume failed");});
        Test("cancel wakes pause and stays terminal",()=>{using var c=new JobControl();c.RequestPause();var task=Task.Run(()=>{Canceled(()=>c.Checkpoint("fixture"));});Check(SpinWait.SpinUntil(()=>c.IsPaused,5000),"Did not pause");c.RequestCancel();c.RequestCancel();c.Resume();c.RequestPause();Check(task.Wait(5000),"Cancel did not wake pause");Check(c.CancellationRequested&&!c.PauseRequested,"Cancel not terminal");Canceled(()=>c.Checkpoint("again"));});
        Test("bounded streams retain cap and drain excess",()=>{var output=Engine.DrainBoundedAsync(new StringReader("abcdefghijklmnop"),5).GetAwaiter().GetResult();Check(output.Text=="abcde"&&output.Truncated&&output.TotalCharacters==16,"Bounded drain lost count or exceeded retained cap");});
        Test("repeated progress bounded before callback with immediate transitions",()=>{var reports=new List<JobProgress>();var progress=new InlineProgress(reports.Add);var watch=Stopwatch.StartNew();for(int i=0;i<20000;i++)JobControl.Publish(progress,new("Hashing source","Reading",i,20000),true);watch.Stop();Check(reports.Count<=Math.Ceiling(watch.Elapsed.TotalMilliseconds/100)+2,"Repeated progress exceeded100ms callback bound");int before=reports.Count;JobControl.Publish(progress,new("Next phase","Changed phase"),true);JobControl.Publish(progress,new("Next phase","Paused",IsPaused:true),true);JobControl.Publish(progress,new("Next phase","Cancel pending",IsPaused:true,CancellationPending:true),true);JobControl.Publish(progress,new("Next phase","Final report"));Check(reports.Count==before+4,"Phase/pause/cancel/final transition delayed");});
        Test("throttling does not skip cancellation checkpoints",()=>{using var c=new JobControl();int reports=0;bool acknowledged=false;var progress=new InlineProgress(p=>{reports++;acknowledged|=p.CancellationPending;});int checkpoint=0;Canceled(()=>{for(;checkpoint<20000;checkpoint++){if(checkpoint==5000)c.RequestCancel();c.Checkpoint("Hashing source",progress,checkpoint,20000,true);}});Check(checkpoint==5000&&acknowledged&&reports<100,"Throttling skipped a safe cancellation checkpoint or flooded callbacks");});
        Test("controlled query defers cancel until child exit and drains",()=>{using var c=new JobControl();string executable=Environment.ProcessPath!;var info=new ProcessStartInfo(executable){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true};if(Path.GetFileNameWithoutExtension(executable).Equals("dotnet",StringComparison.OrdinalIgnoreCase))info.ArgumentList.Add(typeof(Engine).Assembly.Location);info.ArgumentList.Add("--controlled-query-fixture");using var child=Process.Start(info)??throw new Exception("Cannot start controlled fixture");var observed=Engine.ObserveProcessAsync(child,TimeSpan.FromMilliseconds(20));c.RequestCancel();Check(!observed.IsCompleted,"Fixture unexpectedly complete before deferred wait");var result=observed.GetAwaiter().GetResult();Check(child.HasExited&&result.ExitCode==0&&result.Stdout.Text.Contains("fixture-end",StringComparison.Ordinal)&&result.Stderr.Text.Contains("fixture-error-end",StringComparison.Ordinal)&&result.ExceededBudget,"Child lifetime/drains not observed");Canceled(()=>c.Checkpoint("after controlled query"));});
        Test("failed query dominates pending cancellation",()=>{using var c=new JobControl();string executable=Environment.ProcessPath!;var info=new ProcessStartInfo(executable){UseShellExecute=false,RedirectStandardOutput=true,RedirectStandardError=true,CreateNoWindow=true};if(Path.GetFileNameWithoutExtension(executable).Equals("dotnet",StringComparison.OrdinalIgnoreCase))info.ArgumentList.Add(typeof(Engine).Assembly.Location);info.ArgumentList.Add("--controlled-query-failure-fixture");using var child=Process.Start(info)??throw new Exception();var observed=Engine.ObserveProcessAsync(child,TimeSpan.FromSeconds(5));c.RequestCancel();var result=observed.GetAwaiter().GetResult();try{Engine.VerifyObservedQuery(result);c.Checkpoint("after failure");throw new Exception("Failure was ignored");}catch(DismQueryException ex){Check(ex.ExitCode==17,"Wrong child failure");}});
        string root=Path.Combine(Path.GetTempPath(),"WinISOPilot-controls-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
        try{
            string source=Path.Combine(root,"source.iso");File.WriteAllBytes(source,new byte[3*1024*1024]);string original=Engine.Hash(source);
            Test("hash pause resume yields same source identity",()=>{using var c=new JobControl();int requested=0;var progress=new InlineProgress(p=>{if(Interlocked.Exchange(ref requested,1)==0)c.RequestPause();});var task=Task.Run(()=>Engine.HashControlled(source,c,progress,"hash fixture"));Check(SpinWait.SpinUntil(()=>c.IsPaused,5000),"Hash checkpoint did not pause");c.Resume();Check(task.GetAwaiter().GetResult()==original,"Hash changed after pause/resume");});
            Test("pause during unpausable final hash cannot stall finalization",()=>{using var c=new JobControl();var progress=new InlineProgress(p=>{if(p.Completed>=1024*1024)c.RequestPause();});var task=Task.Run(()=>{string hash=Engine.HashControlled(source,c,progress,"Verifying source identity",false);c.FinalCheckpoint("Finalizing");return hash;});Check(task.Wait(5000),"Final phase paused without UI escape");Check(task.Result==original&&!c.IsPaused&&!c.PauseRequested,"Final checkpoint did not clear pending pause");});
            Test("final checkpoint still acknowledges cancellation",()=>{using var c=new JobControl();c.RequestPause();c.RequestCancel();Canceled(()=>c.FinalCheckpoint("Finalizing"));Check(!c.IsPaused,"Final cancellation remained paused");});
            Test("cancel before inspection creates no output or attachment",()=>{using var c=new JobControl();c.RequestCancel();string output=Path.Combine(root,"not-created");Canceled(()=>Engine.Inspect(source,output,c).GetAwaiter().GetResult());Check(!Directory.Exists(output),"Canceled startup created output");});
            Test("cancel during initial hash never attaches and retains integrity unknown",()=>{using var c=new JobControl();var progress=new InlineProgress(p=>{if(p.Phase=="Hashing source")c.RequestCancel();});string output=Path.Combine(root,"partial-hash");Canceled(()=>Engine.Inspect(source,output,c,progress).GetAwaiter().GetResult());string native=File.ReadAllText(Path.Combine(output,"native-result.json"));Check(native.Contains("NotOpened",StringComparison.Ordinal),"Native attachment attempted before complete hash");Check(!Engine.PreviewCanceledCleanup(output,c.RunId).CanDelete,"Partial initial identity allowed cleanup");Check(Engine.Hash(source)==original,"Source changed");});
            passed+=Engine.RunCleanupFixtureTests(root,source,original);
        }finally{Directory.Delete(root,true);}
        Console.WriteLine($"{passed} core control/cleanup tests passed; native failure paths were not fault-injected.");return passed;
    }
}
public static partial class Engine
{
    internal static int RunCleanupFixtureTests(string root,string source,string sourceHash)
    {
        int count=0;void Test(string name,Action action){action();Console.WriteLine("PASS "+name);count++;}void Check(bool condition){if(!condition)throw new Exception("Cleanup fixture assertion failed");}
        InspectionRun Fixture(string name,string status="Canceled"){string output=NewFolder(Path.Combine(root,name));var run=BeginInspectionRun(output,source,Guid.NewGuid());File.WriteAllText(Path.Combine(output,"native-result.json"),"fixture diagnostics only");run.Track("native-result.json");run.Terminal=status;run.NativeFinished=true;run.Freeze();run.Finished=status!="Active";return run;}
        Test("cleanup deletes only canceled owned diagnostics",()=>{var run=Fixture("owned");var preview=PreviewCanceledCleanup(run.Output,run.Id);Check(preview.CanDelete&&preview.Files.Count==1);var result=CleanupCanceledJob(run.Output,run.Id);Check(result.DirectoryRemoved&&result.Removed.Count==1&&!Directory.Exists(run.Output)&&Hash(source)==sourceHash);});
        Test("cleanup wrong run id rejected",()=>{var run=Fixture("wrong-id");Check(!PreviewCanceledCleanup(run.Output,Guid.NewGuid()).CanDelete);});
        Test("cleanup wrong purpose marker rejected",()=>{var run=Fixture("wrong-purpose");string path=Path.Combine(run.Output,".imageguide-owned");File.WriteAllText(path,File.ReadAllText(path).Replace("inspection","plan",StringComparison.Ordinal));Check(!PreviewCanceledCleanup(run.Output,run.Id).CanDelete);});
        Test("cleanup byte-changed semantic-equal marker rejected",()=>{var run=Fixture("marker-bytes");File.AppendAllText(Path.Combine(run.Output,".imageguide-owned"),Environment.NewLine);Check(!PreviewCanceledCleanup(run.Output,run.Id).CanDelete);Check(CleanupCanceledJob(run.Output,run.Id).Removed.Count==0);});
        Test("cleanup empty historical marker rejected",()=>{var run=Fixture("old-marker");File.WriteAllText(Path.Combine(run.Output,".imageguide-owned"),"");Check(!PreviewCanceledCleanup(run.Output,run.Id).CanDelete);});
        Test("cleanup active and failed jobs rejected",()=>{foreach(string status in new[]{"Active","Failed","Complete"}){var run=Fixture("state-"+status,status);Check(!PreviewCanceledCleanup(run.Output,run.Id).CanDelete);}});
        Test("cleanup unexpected entries retained without recursion",()=>{var run=Fixture("unknown");File.WriteAllText(Path.Combine(run.Output,"keep.txt"),"foreign");Directory.CreateDirectory(Path.Combine(run.Output,"keep-dir"));var preview=PreviewCanceledCleanup(run.Output,run.Id);Check(preview.CanDelete);var result=CleanupCanceledJob(run.Output,run.Id);Check(!result.DirectoryRemoved&&File.Exists(Path.Combine(run.Output,"keep.txt"))&&Directory.Exists(Path.Combine(run.Output,"keep-dir"))&&result.Retained.Contains("keep.txt"));});
        Test("cleanup changed after preview retained",()=>{var run=Fixture("changed");Check(PreviewCanceledCleanup(run.Output,run.Id).CanDelete);File.WriteAllText(Path.Combine(run.Output,"native-result.json"),"changed after approval preview");var result=CleanupCanceledJob(run.Output,run.Id);Check(result.Removed.Count==0&&File.Exists(Path.Combine(run.Output,"native-result.json")));});
        Test("cleanup changed before preview retained",()=>{var run=Fixture("changed-before");File.WriteAllText(Path.Combine(run.Output,"native-result.json"),"foreign replacement before preview");Check(!PreviewCanceledCleanup(run.Output,run.Id).CanDelete);Check(File.Exists(Path.Combine(run.Output,"native-result.json")));});
        Test("cleanup locked file retained",()=>{var run=Fixture("locked");Check(PreviewCanceledCleanup(run.Output,run.Id).CanDelete);using var held=new FileStream(Path.Combine(run.Output,"native-result.json"),FileMode.Open,FileAccess.ReadWrite,FileShare.None);var result=CleanupCanceledJob(run.Output,run.Id);Check(!result.DirectoryRemoved&&result.Errors.Count>0);});
        var reparse=Fixture("reparse");string reparsePath=Path.Combine(reparse.Output,"native-result.json");File.Delete(reparsePath);
        try{File.CreateSymbolicLink(reparsePath,source);Test("cleanup reparse alias retained",()=>{Check(!PreviewCanceledCleanup(reparse.Output,reparse.Id).CanDelete);Check(Hash(source)==sourceHash);});}catch(Exception ex) when(ex is UnauthorizedAccessException or IOException){Console.WriteLine("SKIP reparse fixture: OS did not permit symbolic-link creation; reparse guard reviewed statically.");}
        Test("cleanup unresolved hash rejected",()=>{var run=Fixture("hash-unknown");run.BeforeHashStarted=true;run.BeforeHashComplete=true;run.AfterHashComplete=false;Check(!PreviewCanceledCleanup(run.Output,run.Id).CanDelete);});
        Test("cleanup restart latch blocks deletion",()=>{var run=Fixture("restart-latch");try{RequireRestart("simulated control guard fixture, not a native fault");Check(!PreviewCanceledCleanup(run.Output,run.Id).CanDelete);}finally{restartReason=null;Interlocked.Exchange(ref restartRequired,0);}});
        Test("cleanup never changes fixture source",()=>Check(Hash(source)==sourceHash));
        return count;
    }
}
